    #[test]
    fn restore_with_carry_oplog_preserves_timeline() {
        let dir = tempfile::tempdir().unwrap();
        let src = dir.path().join("src");
        std::fs::create_dir_all(&src).unwrap();
        let src_seqs: Vec<i64> = {
            let s = Storage::open(src.to_str().unwrap()).unwrap();
            s.insert(
                "app",
                "c",
                vec![
                    encode_doc(&doc! {"_id": 1i32}).unwrap(),
                    encode_doc(&doc! {"_id": 2i32}).unwrap(),
                ],
                true,
            )
            .unwrap();
            // Async lane: read-after-write needs the drainer flushed.
            s.flush_oplog();
            s.read_oplog(1, 100)
                .unwrap()
                .iter()
                .map(|(q, _)| *q)
                .collect()
        };

        // carry_oplog = true: the restored store keeps the same oplog seqs ...
        let carried = dir.path().join("carried");
        replay::restore_to_timestamp(
            src.to_str().unwrap(),
            carried.to_str().unwrap(),
            None,
            None,
            true,
        )
        .unwrap();
        let r = Storage::open(carried.to_str().unwrap()).unwrap();
        let restored_seqs: Vec<i64> = r
            .read_oplog(1, 100)
            .unwrap()
            .iter()
            .map(|(q, _)| *q)
            .collect();
        assert_eq!(restored_seqs, src_seqs);
        let tail = r.oplog_tail_seq();
        r.insert(
            "app",
            "c",
            vec![encode_doc(&doc! {"_id": 3i32}).unwrap()],
            true,
        )
        .unwrap();
        // A fresh write continues the timeline, after everything carried.
        assert!(r.oplog_tail_seq() > tail);
        drop(r);

        // ... while the default (no carry) leaves the restored oplog empty.
        let fresh = dir.path().join("fresh");
        replay::restore_to_timestamp(
            src.to_str().unwrap(),
            fresh.to_str().unwrap(),
            None,
            None,
            false,
        )
        .unwrap();
        let f = Storage::open(fresh.to_str().unwrap()).unwrap();
        // Only what the new store wrote when it was made.
        let own = f.read_oplog(1, 100).unwrap();
        assert_eq!(own.len(), 2);
        assert!(f.oplog_reaches_genesis().unwrap());
    }

    #[test]
    fn min_retention_keeps_young_entries_past_the_cap() {
        // `replSetResizeOplog`'s `minRetentionHours`: no entry younger than
        // the floor is pruned, whatever the entry cap.
        let dir = tempfile::tempdir().unwrap();
        let s = Storage::open(dir.path().to_str().unwrap()).unwrap();
        let enc = |id: i32| encode_doc(&doc! {"_id": id}).unwrap();
        for id in 0..6 {
            s.insert("app", "c", vec![enc(id)], true).unwrap();
        }
        // Sized to hold two entries. The floor goes in first, as
        // `replSetResizeOplog` applies both at once: `set_oplog_max_bytes`
        // wakes the background pruner, which would otherwise apply the cap
        // before the floor exists (main's CI, `rust-storage
        // (storage-nonlogged)`, 2026-11-23, where the setter's checkpoint
        // widens that window).
        let held = s.read_oplog(1, 100).unwrap();
        let two: usize = held[held.len() - 2..].iter().map(|(_, b)| b.len()).sum();
        s.set_oplog_min_retention_seconds(3600);
        s.set_oplog_max_bytes(two as i64).unwrap();
        assert_eq!(s.prune_oplog(None).unwrap(), 0);
        assert!(s.read_oplog(1, 100).unwrap().len() >= 6);
        // An hour and more later, the cap applies again.
        s.set_oplog_min_retention_seconds(3600);
        let later = now_secs() + 7200;
        assert!(s.prune_oplog(Some(later)).unwrap() > 0);
        s.set_oplog_min_retention_seconds(0);
    }

    #[test]
    fn v2_restore_reaches_before_pruned_floor() {
        let dir = tempfile::tempdir().unwrap();
        let archive = dir.path().join("archive");
        let archive_s = archive.to_str().unwrap().to_string();
        let src = dir.path().join("src");
        std::fs::create_dir_all(&src).unwrap();
        let enc = |id: i32| encode_doc(&doc! {"_id": id}).unwrap();
        {
            let mut s = Storage::open(src.to_str().unwrap()).unwrap();
            s.set_oplog_archive_dir(Some(archive_s.clone()));
            // The first insert also records the collection's creation.
            s.insert("app", "c", vec![enc(1), enc(2)], true).unwrap();
            s.archive_base_snapshot(&archive_s).unwrap(); // base head = the batch's entry
            s.insert("app", "c", vec![enc(3)], true).unwrap();
            s.insert("app", "c", vec![enc(4)], true).unwrap();
            s.insert("app", "c", vec![enc(5)], true).unwrap();
            let rows = s.read_oplog(1, 100).unwrap();
            let all: Vec<i64> = rows.iter().map(|r| r.0).collect();
            // The initiating no-op and the creation of
            // `config.system.indexBuilds`, the creation, the one `applyOps`
            // of the first batch, then three inserts.
            assert_eq!(all.len(), 7);
            // Sized to hold the last two entries: the first five are archived.
            let two: usize = rows[rows.len() - 2..].iter().map(|(_, b)| b.len()).sum();
            s.set_oplog_max_bytes(two as i64).unwrap();
            // `set_oplog_max_bytes` wakes the background pruner, which runs
            // the same sweep (archive included) and may drop some or all of
            // the five first: this call's count is an upper bound, and the
            // state below is what the cap must leave.
            let pruned = s.prune_oplog(None).unwrap();
            assert!(pruned <= 5, "pruned {pruned}");
            // The live oplog no longer reaches the third entry.
            assert_eq!(s.oplog_floor_seq().unwrap(), all[5]);
            assert!(!s.oplog_reaches_genesis().unwrap());
        }

        // v1 can't restore the src (floor past genesis); v2 stitches base + segments.
        let out = dir.path().join("restored");
        pitr_archive::restore_from_archive_dir(
            &archive_s,
            out.to_str().unwrap(),
            None,
            None,
            false,
        )
        .unwrap();
        let r = Storage::open(out.to_str().unwrap()).unwrap();
        let mut ids: Vec<i32> = r
            .find_matching("app", "c", &doc! {})
            .unwrap()
            .iter()
            .map(|b| decode_doc(b).unwrap().get_i32("_id").unwrap())
            .collect();
        ids.sort();
        assert_eq!(ids, vec![1, 2, 3]); // base (1,2) + the archived third insert
    }

    #[test]
    fn opportunistic_prune_bounds_oplog_from_writes() {
        // The write path prunes the oplog every OPLOG_PRUNE_INTERVAL emits, so a
        // long-running server bounds its oplog from writes alone — with NO
        // explicit prune_oplog call and NO noop-heartbeat sweeper (the default).
        let dir = tempfile::tempdir().unwrap();
        let s = Storage::open(dir.path().to_str().unwrap()).unwrap();
        // Ten entries' worth of bytes, about.
        s.set_oplog_max_bytes(10 * 100).unwrap();
        let enc = |id: i32| encode_doc(&doc! {"_id": id}).unwrap();
        let total = OPLOG_PRUNE_INTERVAL as i32 + 1; // cross the threshold once
        for i in 0..total {
            s.insert("app", "c", vec![enc(i)], true).unwrap();
        }
        // The opportunistic prune at the OPLOG_PRUNE_INTERVAL-th emit (sync:
        // writer-side, synchronous; async: drainer-side as rows land) trims
        // the oplog to the 10-entry cap; only the handful of writes after it
        // remain. In async mode the cadence sweep runs CONCURRENTLY on the
        // drainer thread — `flush_oplog` guarantees the rows landed, not that
        // an in-flight sweep's deletes finished — so poll briefly: the
        // invariant is "write volume alone eventually bounds the oplog".
        // Sync mode passes on the first iteration.
        s.flush_oplog();
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
        let live = loop {
            let live = s.read_oplog(1, 1_000_000).unwrap().len();
            if live <= 50 || std::time::Instant::now() >= deadline {
                break live;
            }
            std::thread::sleep(std::time::Duration::from_millis(20));
        };
        assert!(
            live <= 50,
            "oplog not opportunistically pruned: {live} live rows after {total} writes"
        );
        // Pruning the oplog never touches document data.
        assert_eq!(
            s.find_matching("app", "c", &doc! {}).unwrap().len() as i32,
            total
        );
    }

    #[test]
    fn v2_segment_roundtrip() {
        let dir = tempfile::tempdir().unwrap();
        let archive = dir.path().to_str().unwrap();
        let rows = vec![
            (
                1i64,
                doc! {"op": "i", "ns": "a.b", "o": {"_id": 1i32}},
                None,
            ),
            (
                2i64,
                doc! {"op": "i", "ns": "a.b", "o": {"_id": 2i32}},
                Some(doc! {"_id": 2i32, "old": true}),
            ),
        ];
        pitr_archive::write_segment(archive, &rows, 0).unwrap();
        let got = pitr_archive::iter_archived_oplog(archive).unwrap();
        assert_eq!(got.len(), 2);
        assert_eq!(got[0].0, 1);
        assert_eq!(got[1].2, Some(doc! {"_id": 2i32, "old": true}));
        assert!(pitr_archive::is_archive_dir(archive));
    }

    #[test]
    fn an_entry_is_the_keystring_then_the_recordid() {
        // `KeyString(values) + RecordId`, the TypeBits as the value.
        let shape = KeyShape::new(&doc! {"k": 1i32}, None, BinDataOrder::Mongod);
        let entry = shape.entry(&[Bson::Int32(7)], &RecordId::Long(1)).unwrap();
        let mut b =
            keystring::Builder::new(keystring::Version::V1, keystring::Ordering::all_ascending());
        b.append_bson_element(&Bson::Int32(7)).unwrap();
        b.append_record_id_long(1).unwrap();
        let (key, tb) = b.finish().unwrap();
        assert_eq!(entry.key, key);
        assert_eq!(entry.type_bits, tb.serialize());
        assert_eq!(
            ixkeys::entry_rid(&entry.key, false),
            Some(RecordId::Long(1))
        );
        assert_eq!(
            ixkeys::entry_prefix(&entry.key, false),
            Some(shape.exact(&[Bson::Int32(7)]).unwrap().as_slice())
        );
    }

    #[test]
    fn an_entry_orders_by_recordid_within_a_key() {
        // Within one key the RecordId's encoding keeps the B-tree in
        // RecordId (insertion) order.
        let shape = KeyShape::new(&doc! {"k": 1i32}, None, BinDataOrder::Mongod);
        let at = |rid: i64| {
            shape
                .entry(&[Bson::String("k".into())], &RecordId::Long(rid))
                .unwrap()
                .key
        };
        assert!(at(1) < at(2));
        assert!(at(2) < at(300));
        assert!(at(300) < at(i64::MAX));
    }

    #[test]
    fn a_key_that_is_not_an_entry_has_no_recordid() {
        // A key too short to hold a RecordId reports None rather than a
        // RecordId read out of other bytes, which would fetch the wrong
        // document.
        assert_eq!(ixkeys::entry_rid(b"k", false), None);
        assert_eq!(ixkeys::entry_rid(b"", false), None);
    }

    /// A dotted sort key walks ONE array level. `x: [{y: 1}]` HAS an `x.y` and
    /// must rank among the documents that do; `x: [[{y: 5}]]` does not, because
    /// that is two levels — mongod agrees on both (probed 8.2.11, 2026-09-06).
    /// The sort used `get_path`, which walks none.
    #[test]
    fn a_dotted_sort_key_walks_one_array_level() {
        let cases: [(Document, Option<i32>); 5] = [
            (doc! {"x": [{"y": 1i32}]}, Some(1)),
            (doc! {"x": {"y": 1i32}}, Some(1)),
            // Several values: ascending takes the minimum.
            (doc! {"x": [{"y": 5i32}, {"y": 1i32}]}, Some(1)),
            // Two levels is not one: absent.
            (doc! {"x": [[{"y": 5i32}]]}, None),
            (doc! {"x": [5i32]}, None),
        ];
        for (d, want) in cases {
            let got = sort_field_value(&d, "x.y", false);
            match want {
                Some(n) => assert_eq!(got, Bson::Int32(n), "{d:?}"),
                None => assert_eq!(got, Bson::Null, "{d:?} has no x.y"),
            }
        }
        // Descending takes the maximum of the several values.
        assert_eq!(
            sort_field_value(&doc! {"x": [{"y": 5i32}, {"y": 1i32}]}, "x.y", true),
            Bson::Int32(5)
        );
    }

    /// The regression this fix nearly shipped: the representative-element rule
    /// was briefly applied TWICE, which resolved `x: [[5]]` to the number 5
    /// instead of the array `[5]` and moved it out of the array group in an
    /// UNDOTTED sort.
    #[test]
    fn an_undotted_sort_key_descends_exactly_once() {
        assert_eq!(
            sort_field_value(&doc! {"x": [[5i32]]}, "x", false),
            Bson::Array(vec![Bson::Int32(5)]),
            "one level: the representative element is the inner ARRAY"
        );
        assert_eq!(
            sort_field_value(&doc! {"x": [5i32]}, "x", false),
            Bson::Int32(5)
        );
        assert_eq!(
            sort_field_value(&doc! {"x": 5i32}, "x", false),
            Bson::Int32(5)
        );
        // Descending picks the maximum element, as before.
        assert_eq!(
            sort_field_value(&doc! {"x": [1i32, 9i32]}, "x", true),
            Bson::Int32(9)
        );
    }

    /// A DESCENDING sort must reverse a PREFIX chain, which the old
    /// invert-the-bytes key could not: `""`'s key is a strict prefix of
    /// `"a"`'s, and a shorter byte string sorts first both before and after
    /// inversion. So `["", "a", "ab", "abc", "b"]` sorted descending came back
    /// `["", "b", "a", "ab", "abc"]` -- every prefix chain ascending, inside a
    /// descending result (measured against mongod 8.2.11, 2026-09-06).
    #[test]
    fn descending_sort_reverses_a_prefix_chain() {
        let spec = vec![("x".to_string(), -1)];
        let docs: Vec<Document> = ["", "a", "ab", "abc", "b"]
            .iter()
            .map(|s| doc! {"x": *s})
            .collect();
        let mut keyed: Vec<(Vec<SortPart>, &str)> = docs
            .iter()
            .zip(["", "a", "ab", "abc", "b"])
            .map(|(d, label)| (sort_key(d, &spec, None).unwrap(), label))
            .collect();
        keyed.sort_by(|a, b| compare_sort_keys(&a.0, &b.0, &spec));
        assert_eq!(
            keyed.iter().map(|(_, l)| *l).collect::<Vec<_>>(),
            vec!["b", "abc", "ab", "a", ""]
        );
    }

    #[test]
    fn ascending_sort_is_unchanged_by_the_comparator() {
        let spec = vec![("x".to_string(), 1)];
        let labels = ["", "a", "ab", "abc", "b"];
        let mut keyed: Vec<(Vec<SortPart>, &str)> = labels
            .iter()
            .map(|s| (sort_key(&doc! {"x": *s}, &spec, None).unwrap(), *s))
            .collect();
        keyed.sort_by(|a, b| compare_sort_keys(&a.0, &b.0, &spec));
        assert_eq!(keyed.iter().map(|(_, l)| *l).collect::<Vec<_>>(), labels);
    }

    /// Direction is per FIELD, so a mixed compound sort must reverse only the
    /// columns that ask for it.
    #[test]
    fn compare_sort_keys_applies_direction_per_field() {
        type Row<'a> = (Vec<SortPart>, (&'a str, &'a str));
        let spec = vec![("a".to_string(), 1), ("b".to_string(), -1)];
        let mut rows: Vec<Row<'_>> = [("x", ""), ("x", "z"), ("w", "")]
            .iter()
            .map(|(a, b)| {
                (
                    sort_key(&doc! {"a": *a, "b": *b}, &spec, None).unwrap(),
                    (*a, *b),
                )
            })
            .collect();
        rows.sort_by(|l, r| compare_sort_keys(&l.0, &r.0, &spec));
        // `a` ascending, then `b` descending -- and `""` must come LAST in `b`.
        assert_eq!(
            rows.iter().map(|(_, v)| *v).collect::<Vec<_>>(),
            vec![("w", ""), ("x", "z"), ("x", "")]
        );
    }

    /// An empty array still sorts between MinKey and Null, and the comparator
    /// (not a hand-inverted byte pattern) now supplies the direction.
    #[test]
    fn an_empty_array_keeps_its_place_in_both_directions() {
        for (dir, want) in [(1, vec!["[]", "null", "s"]), (-1, vec!["s", "null", "[]"])] {
            let spec = vec![("x".to_string(), dir)];
            let rows: Vec<(Document, &str)> = vec![
                (doc! {"x": []}, "[]"),
                (doc! {"x": Bson::Null}, "null"),
                (doc! {"x": "s"}, "s"),
            ];
            let mut keyed: Vec<(Vec<SortPart>, &str)> = rows
                .iter()
                .map(|(d, l)| (sort_key(d, &spec, None).unwrap(), *l))
                .collect();
            keyed.sort_by(|a, b| compare_sort_keys(&a.0, &b.0, &spec));
            assert_eq!(keyed.iter().map(|(_, l)| *l).collect::<Vec<_>>(), want);
        }
    }

